  /* Estilos propios de cada elemento (color, letra, fondo, esquinas, ocultar) elegidos en el editor visual. */
  function applyElementStyles(settings,{preview=false}={}){
    const color=value=>/^#[0-9a-f]{3}([0-9a-f]{3})?$/i.test(String(value||''))?String(value):null;
    const number=(value,min,max)=>{const parsed=Number(value);return Number.isFinite(parsed)?Math.max(min,Math.min(max,parsed)):null;};
    const transforms={upper:'uppercase',lower:'lowercase',title:'capitalize',none:'none'},aligns={left:'left',center:'center',right:'right'},weights={normal:'400',medium:'500',bold:'700'};
    const rules=[];
    for(const [id,style] of Object.entries(settings.elementStyles||{})){
      if(!/^[\w.-]{1,80}$/.test(id)||!style||typeof style!=='object')continue;
      const props=[],selector=`[data-edit-id="${id}"]`,strong=`${selector}${selector}`;
      if(color(style.color))props.push(`color:${style.color}`);
      if(color(style.background))props.push(`background:${style.background}`,`background-color:${style.background}`);
      if(color(style.borderColor))props.push(`border-color:${style.borderColor}`,'border-style:solid',`border-width:${number(style.borderWidth,0,8)??1}px`);
      if(number(style.fontSize,8,96)!==null)props.push(`font-size:${number(style.fontSize,8,96)}px`);
      if(weights[style.fontWeight])props.push(`font-weight:${weights[style.fontWeight]}`);
      if(transforms[style.textTransform])props.push(`text-transform:${transforms[style.textTransform]}`);
      if(aligns[style.textAlign])props.push(`text-align:${aligns[style.textAlign]}`);
      if(number(style.radius,0,999)!==null)props.push(`border-radius:${number(style.radius,0,999)}px`);
      if(number(style.letterSpacing,-2,12)!==null)props.push(`letter-spacing:${number(style.letterSpacing,-2,12)}px`);
      if(props.length)rules.push(`${strong}{${props.map(prop=>`${prop}!important`).join(';')}}`);
      if(color(style.color))rules.push(`${selector} *:not(img):not(svg):not(path){color:inherit!important}`);
      const mobileSize=number(style.fontSizeMobile,8,96),ghost=`{opacity:.35!important;outline:2px dashed #e0702b!important;outline-offset:2px}`;
      if(mobileSize!==null)rules.push(`@media(max-width:768px){${strong}{font-size:${mobileSize}px!important}}`);
      if(style.showOn==='desktop')rules.push(`@media(max-width:768px){${selector}${preview?ghost:'{display:none!important}'}}`);
      if(style.showOn==='mobile')rules.push(`@media(min-width:769px){${selector}${preview?ghost:'{display:none!important}'}}`);
      if(style.hidden===true)rules.push(preview?`${selector}{opacity:.35!important;outline:2px dashed #e0702b!important;outline-offset:2px}`:`${selector}{display:none!important}`);
    }
    let node=document.getElementById('catalog-element-styles');
    if(!node){node=document.createElement('style');node.id='catalog-element-styles';document.head.append(node);}
    node.textContent=rules.join('\n');
  }
  function apply(raw,{preview=false}={}){const settings=schema.migrate(raw);window.CatalogSiteSettings=settings;applyTokens(settings);applyMeta(settings);applyHeader(settings);applyAnnouncementBar(settings,{preview});applyHero(settings);applySections(settings);applySearchAndFilters(settings);applyFooter(settings);applyTexts(settings);applyCart(settings);applyFloatingWhatsapp(settings);applyCard(settings);applyPricing(settings);applyColorSwatches(settings);applyWelcome(settings,{preview});applyMaintenance(settings);applyElementStyles(settings,{preview});document.body.classList.toggle('site-compact-cards',settings.grid.compactCards===true);document.body.dataset.cardAlign=settings.card.textAlign||'left';document.body.dataset.cardHover=settings.grid.hover||'lift';document.body.dataset.cartSide=settings.cart.side||'right';document.body.dataset.preview=String(preview);markEditable();window.dispatchEvent(new CustomEvent('catalog-site-settings-applied',{detail:settings}));return settings;}
